import { useEffect, useState } from 'react';
import { RefreshCw, Plus, FlaskConical, ClipboardCheck } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { useRolePermissions } from '../../hooks/useRolePermissions';
import { VENDOR_WRITE_ROLES } from '../../lib/vendor-constants';
import { fetchSamples, fetchSamplingOptions, SAMPLE_TYPES, SAMPLE_STATUSES, QC_DECISIONS, qcBadge, missingSamplingBackend } from '../../lib/vendor-sampling';
import SampleFormModal from './SampleFormModal';
import SampleDetailModal from './SampleDetailModal';
import QCParametersModal from './QCParametersModal';

export default function VendorSamplesPanel({ candidateId = '', readOnly = false, mode = 'samples', onChanged }) {
  const { role, profile } = useAuth(), { hasAccess, loading: permissionsLoading } = useRolePermissions();
  const canSamples = hasAccess('vendor_samples'), canQC = hasAccess('vendor_qc');
  const allowed = !permissionsLoading && ['sourcing', 'hrd', 'super_admin', 'direksi'].includes(role?.role_name) && (candidateId ? canSamples || canQC : mode === 'qc' ? canQC : canSamples);
  const writer = allowed && !readOnly && VENDOR_WRITE_ROLES.includes(role?.role_name), canWriteSamples = writer && canSamples, canWriteQC = writer && canQC;
  const [options, setOptions] = useState({ candidates: [], users: [], categories: [], parameters: [], employees: [] });
  const [rows, setRows] = useState([]), [count, setCount] = useState(0), [loading, setLoading] = useState(true), [error, setError] = useState(''), [pendingBackend, setPendingBackend] = useState(false);
  const [version, setVersion] = useState(0), [searchInput, setSearchInput] = useState(''), [search, setSearch] = useState(''), [status, setStatus] = useState(''), [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false), [related, setRelated] = useState(null), [selected, setSelected] = useState(''), [master, setMaster] = useState(false);
  useEffect(() => { const timer = setTimeout(() => { setSearch(searchInput); setPage(0); }, 300); return () => clearTimeout(timer); }, [searchInput]);
  useEffect(() => {
    if (!allowed) return; let ignore = false; setLoading(true); setError(''); setPendingBackend(false);
    Promise.all([fetchSamples({ candidateId, status, search, canQC, page, includeArchived: readOnly }), fetchSamplingOptions(canQC)]).then(([data, opts]) => { if (!ignore) { setRows(data.rows); setCount(data.count); setOptions(opts); } }).catch((err) => { if (!ignore) { setPendingBackend(missingSamplingBackend(err)); setError(err.message); } }).finally(() => { if (!ignore) setLoading(false); });
    return () => { ignore = true; };
  }, [allowed, candidateId, status, search, canQC, page, version, readOnly]);
  const refresh = () => { setVersion((n) => n + 1); onChanged?.(); };
  if (permissionsLoading) return <p role="status" className="text-ink-400">Memuat akses sampel…</p>;
  if (!allowed) return <p className="text-ink-400">Anda tidak memiliki akses modul sampel/QC ini.</p>;
  return <div className="space-y-5 min-w-0">
    <div className="flex flex-wrap justify-between items-start gap-3"><div><h2 className="font-semibold text-lg text-white inline-flex items-center gap-2">{mode === 'qc' ? <ClipboardCheck size={19} /> : <FlaskConical size={19} />}{mode === 'qc' ? 'Hasil QC Sampel' : 'Pengujian Sampel'}</h2><p className="text-xs text-ink-400 mt-1">Catat spesifikasi, pengerjaan dan setiap putaran pemeriksaan. Hasil QC tetap terpisah dari persetujuan vendor.</p></div><div className="flex flex-wrap gap-2"><button className="btn-secondary text-sm" onClick={refresh} disabled={loading}><RefreshCw size={14} className={loading ? 'animate-spin' : ''} /> Refresh sampel</button>{!pendingBackend && canQC && ['hrd', 'super_admin'].includes(role?.role_name) && !readOnly && <button className="btn-secondary text-sm" onClick={() => setMaster(true)}>Kelola Rubrik QC</button>}{!pendingBackend && canWriteSamples && <button className="btn-primary text-sm" onClick={() => { setRelated(null); setCreating(true); }}><Plus size={14} /> Tambah Sampel</button>}</div></div>
    <div className="card p-4 flex flex-col sm:flex-row gap-3"><div className="flex-1"><label className="label" htmlFor={`sample-search-${mode}-${candidateId}`}>Cari sampel / vendor</label><input id={`sample-search-${mode}-${candidateId}`} className="input" value={searchInput} onChange={(e) => setSearchInput(e.target.value)} placeholder="Kode sampel, produk atau nama vendor…" /></div><div><label className="label" htmlFor={`sample-status-${mode}-${candidateId}`}>Status sampel</label><select id={`sample-status-${mode}-${candidateId}`} className="input" value={status} onChange={(e) => { setStatus(e.target.value); setPage(0); }}><option value="">Semua status</option>{Object.entries(SAMPLE_STATUSES).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></div></div>
    {pendingBackend ? <p role="status" className="card p-5 text-sm text-ink-400">Fitur sampel dan QC belum diaktifkan. Pendataan vendor, follow-up dan lokasi tetap dapat digunakan.</p> : error ? <p role="alert" className="card p-5 text-sm text-danger-400">Gagal memuat sampel: {error} <button className="underline" onClick={refresh}>Coba lagi</button></p> : loading ? <p role="status" className="card p-6 text-ink-400">Memuat sampel…</p> : <div className="card overflow-hidden">{rows.length === 0 ? <div className="empty-state p-8"><FlaskConical size={32} className="mx-auto text-ink-500" /><p className="text-white font-medium mt-3">Belum ada sampel untuk pilihan ini</p><p className="text-sm text-ink-400 mt-1">Mulai dari brief untuk vendor yang akan diuji.</p></div> : <div className="overflow-x-auto"><table className="table"><thead><tr><th>Sampel / produk</th><th>Vendor</th><th>Jenis / jumlah</th><th>Status</th><th>Target</th>{canQC && <th>QC terakhir</th>}<th>Aksi</th></tr></thead><tbody>{rows.map((s) => <tr key={s.id}><td><span className="font-mono text-xs text-primary-400">{s.sample_code}</span><p className="text-white text-sm">{s.product_code || 'Tanpa kode produk'}</p></td><td className="text-sm">{s.business_name}</td><td className="text-sm">{SAMPLE_TYPES[s.sample_type]}<p className="text-xs text-ink-400">{s.quantity} {s.unit}</p></td><td><span className={s.status === 'SELESAI' ? 'badge-green' : s.status === 'PERLU_REVISI' ? 'badge-orange' : 'badge-blue'}>{SAMPLE_STATUSES[s.status]}</span></td><td className="text-xs">{s.target_date || 'Belum ditetapkan'}</td>{canQC && <td><span className={qcBadge(s.latest_decision)}>{QC_DECISIONS[s.latest_decision] || 'Belum diperiksa'}</span><p className="text-xs text-ink-500 mt-1">{s.qc_count} putaran{s.latest_score != null ? ` · ${s.latest_score}/5` : ''}</p></td>}<td><button className="btn-secondary text-xs" aria-label={`Detail sampel ${s.sample_code}`} onClick={() => setSelected(s.id)}>Detail</button></td></tr>)}</tbody></table></div>}<div className="flex flex-wrap justify-between items-center gap-3 p-4 border-t border-white/5 text-xs text-ink-400"><span>{count} sampel · halaman {page + 1}</span><div className="flex gap-2"><button className="btn-secondary text-xs" disabled={!page} onClick={() => setPage((n) => n - 1)}>Sebelumnya</button><button className="btn-secondary text-xs" disabled={(page + 1) * 25 >= count} onClick={() => setPage((n) => n + 1)}>Berikutnya</button></div></div></div>}
    {creating && <SampleFormModal options={options} candidateId={candidateId} related={related} onClose={() => setCreating(false)} onSaved={() => { setCreating(false); refresh(); }} />}
    {selected && <SampleDetailModal id={selected} canSamples={canSamples} canQC={canQC} canWriteSamples={canWriteSamples} canWriteQC={canWriteQC} readOnly={readOnly} options={options} profileId={profile?.id} onClose={() => setSelected('')} onChanged={refresh} onRelated={(s) => { setSelected(''); setRelated(s); setCreating(true); }} />}
    {master && <QCParametersModal options={options} onClose={() => setMaster(false)} onSaved={refresh} />}
  </div>;
}
